/* @socom-skeleton stub LoadVehicles__8CMissionFUi */
bool CMission::LoadVehicles(unsigned int)
{
	/* 0x1fd570: create every vehicle of the vehicle reader in order (the first one is the
	 * player); recycle entries become spawners. The extra player copies (ftsPlayerCount)
	 * and the player_grid_count grid of copies around the player follow the first one. */
	CCharacterModelCache::m_ModelCache.clear();

	if (theNetwork.m_bNetwork && !theNetwork.m_bSessionMaster)
		return true;

	BodyAnimCallbackList.Clear();
	CVehicleRdr* vehicles = m_vehicleRdr;
	SOCOM_PORT_TRACE("LOAD: %u vehicles, load_ai %u", (unsigned)vehicles->size(), (unsigned)m_load_ai);
	s32 index = 0;

	for (CVehicleRdr::iterator entry = vehicles->begin(); entry != vehicles->end(); ++entry, index++)
	{
		bool first = index == 0;

		if (entry->m_recycle)
		{
			/* 0x1fd620: a spawner - its slot now, its character when a recycled one frees it */
			CSpawners::spawn_map spawn;
			spawn.m_index = CEntity::CreateRecycler()->m_index;
			spawn.m_entry = &*entry;
			spawners.m_spawn.insert(spawners.m_spawn.end(), spawn);
			continue;
		}

		CZSealBody* body = LoadVehicle(&*entry, first);

		if (body != NULL)
			body->m_vehicle_index = (u32)index;

		if (!first || body == NULL)
			continue;

		for (s32 i = 1; i < ftsPlayerCount; i++)
		{
			CZSealBody* copy = LoadVehicle(&*entry, first);
			CZSealBody* seal = copy != NULL && copy->m_type == CEntity::ENT_TYPE_SEAL ? copy : NULL;
			/* port: not written - the ELF stores i at +232 of the copy's controller
			 * (unnamed in DWARF terms here); ftsPlayerCount is 0 without arguments */
			(void)seal;
		}

		s32 count = m_ai_params.player_grid_count;

		if (count == 0)
			continue;

		/* a near-square grid of copies, player_grid_spacing apart, around the player */
		s32 side = (s32)floorf(sqrtf((f32)count));
		s32 rows = 0;

		for (; side <= count; side++)
		{
			if (count % side == 0)
			{
				rows = count / side;
				break;
			}
		}

		f32 spacing = m_ai_params.player_grid_spacing;
		CPnt3D origin;
		origin.x = 0.5f * ((f32)(side - 1) * spacing);
		origin.y = 0.0f;
		origin.z = -spacing;

		for (s32 row = 0; row < rows; row++)
		{
			for (s32 col = 0; col < side; col++)
			{
				CPnt3D pos = origin;
				pos.x += (f32)col * m_ai_params.player_grid_spacing;
				pos.z -= (f32)row * m_ai_params.player_grid_spacing;
				body->m_node->m_matrix.Transform(&pos, 1);
				CZSealBody* copy = LoadVehicle(&*entry, true);
				copy->TeleportTo(&pos, &copy->m_quat);
			}
		}
	}

	CEntity::UpdateTargetList(true);
	CCharacterModelCache::m_ModelCache.clear();

	if (!theNetwork.m_bNetwork)
		CTurret::LoadTurrets();

	return true;
}

/* @socom-skeleton stub LoadVehicle__8CMissionFP16CVehicleRdrEntryb */
CZSealBody * CMission::LoadVehicle(CVehicleRdrEntry *entry, bool first)
{
	/* 0x1fd160: one character of the vehicle reader at its (random) start; the first is
	 * the player. m_load_ai selects the AI characters: 0 none; bit 1 only team 31,
	 * bit 2 not team 3, bit 3 not team 2. */
	if (entry == NULL)
		return NULL;

	entry->Randomize(false);

	if (entry->m_disabled && (!first || theNetwork.m_bNetwork))
		return NULL;

	u32 mask = m_load_ai;
	u32 teams = (u32)entry->m_teamMask;
	bool load = first;

	if (mask != 0 && !first)
	{
		load = true;

		if (mask & 2)
			load = (teams & 0x80000000) != 0;

		if (load && (mask & 4))
			load = (teams & 8) == 0;

		if (load && (mask & 8))
			load = (teams & 4) == 0;
	}

	/* port: not written - the ELF then drops every non-first character not named
	 * ai::isolate_character (0x43a370: 32 bytes, zero in the ELF, no source owner yet);
	 * it is empty, so the test never applies */

	if (!load)
		return NULL;

	CCharacterType* type = CCharacterType::GetByNameMod(entry->m_character);

	if (type == NULL)
		return NULL;

	CPnt3D pos = CPnt3D::zero;
	CQuat rot = CQuat::identity;
	CAiMapLoc loc;

	if (AiMaps.GetLocation(entry->GetStartPos(), loc))
	{
		AiMaps.GetCellCenter(loc, &pos);
		CAiMap::GetDirQuat((CAiMap::DIR)(u8)entry->GetStartDir(), rot, true);
	}

	SEAL_CONTROL_TYPE ctrltype = SEAL_CONTROL_TYPE::CTRL_AI;

	if (first)
	{
		if (doSquirm)
			ctrltype = SEAL_CONTROL_TYPE::CTRL_SQUIRM;
		else if (CEntity::m_list.size() == 0)
			ctrltype = SEAL_CONTROL_TYPE::CTRL_PLAYER;
		else
			ctrltype = SEAL_CONTROL_TYPE::CTRL_MISC;
	}

#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("LOAD: vehicle %s character %s control %d start %s at %d %d %d", entry->m_name, entry->m_character, (int)ctrltype,
		entry->GetStartPos() != NULL ? entry->GetStartPos() : "-", (int)pos.x, (int)pos.y, (int)pos.z);
#endif
	CZSealBody* body = ftsCreateSeal(type, entry->m_name, ctrltype);

	if (body == NULL)
		return NULL;

	body->m_node->SetName(entry->m_name);

	if (entry->m_display_name[0] != '\0')
		body->SetDisplayName(entry->m_display_name);

	body->TeleportTo(&pos, &rot);
	body->SetTeamMask(teams);
	body->m_noshoot = entry->m_noshoot;
	CSealCtrlAi* ai = ((CSealCtrl*)body->m_control)->GetSealCtrlAi();

	if (ai != NULL)
	{
		ai->SetDebug(entry->m_debug);
		ai->m_nofade = entry->m_nofade;
		ai->m_nosnooze = entry->m_nosnooze;
		ai->m_aiParams = entry->m_aiParams;
		ai->m_aiParams.m_veh = entry;
		ai->InitAiBrain();
	}

	return body;
}

/* @socom-skeleton stub InitalizeTeamValves__8CMissionFv */
void CMission::InitalizeTeamValves()
{
	/* 0x1fd0d0: aiteam_00..31 (the living members of each team bit, for the mission
	 * scripts) and player_valve_alive, all temporary and 0 until RefreshTeamValves */
	char name[32];

	for (s32 i = 0; i < 32; i++)
	{
		sprintf(name, "aiteam_%02d", i);
		m_teamValve[i] = CValve::Create(name, 0, VALVE_TYPE::VTYPE_TEMP);
	}

	m_player_valve = CValve::Create("player_valve_alive", 0, VALVE_TYPE::VTYPE_TEMP);
}

/* @socom-skeleton stub RefreshTeamValves__8CMissionFv */
void CMission::RefreshTeamValves()
{
	/* 0x1fcd90: recount from the entities: every team valve to 0, then each living
	 * entity adds 1 to the valve of every team bit it has; the player's seal sets
	 * player_valve_alive to its alive state. The callbacks run on each change (1 set,
	 * 2 cleared). */
	for (s32 i = 0; i < 32; i++)
	{
		CValve* valve = m_teamValve[i];
		bool changed = valve->m_value != 0;
		valve->m_value = 0;

		if (changed)
			valve->MakeCallbacks((VALVE_STATE)2);
	}

	for (CEntityList::iterator it = CEntity::m_list.begin(); it != CEntity::m_list.end(); ++it)
	{
		CEntity* entity = *it;
		CEntity* seal = entity != NULL && entity->m_type == CEntity::ENT_TYPE_SEAL ? entity : NULL;

		if (seal != NULL)
		{
			bool player = seal->m_control != NULL && static_cast<CSealCtrl*>(seal->m_control)->IsPlayer();

			if (player && m_player_valve != NULL)
			{
				u32 alive = entity->m_isAlive ? 1 : 0;
				u32 change = m_player_valve->m_value != alive ? (alive != 0 ? 1 : 2) : 0;
				m_player_valve->m_value = alive;

				if (change)
					m_player_valve->MakeCallbacks((VALVE_STATE)change);
			}
		}

		if (!entity->m_isAlive)
			continue;

		for (u32 bit = 0; (s32)bit < 32; bit++)
		{
			if (!((1 << bit) & entity->m_team))
				continue;

			CValve* valve = m_teamValve[bit];
			u32 count = valve->m_value + 1;
			u32 change = valve->m_value != count ? (count != 0 ? 1 : 2) : 0;
			valve->m_value = count;

			if (change)
				valve->MakeCallbacks((VALVE_STATE)change);
		}
	}

	/* 0x1fcff0: each waiting recycle entry adds its team bits the same way */
	for (std::list<CSpawners::spawn_map>::iterator it = spawners.m_spawn.begin(); it != spawners.m_spawn.end(); ++it)
	{
		u32 teams = (u32)it->m_entry->m_teamMask;

		for (s32 bit = 0; bit < 32; bit++)
		{
			if (!((1 << bit) & teams))
				continue;

			CValve* valve = m_teamValve[bit];
			u32 count = valve->m_value + 1;
			u32 change = valve->m_value != count ? (count != 0 ? 1 : 2) : 0;
			valve->m_value = count;

			if (change)
				valve->MakeCallbacks((VALVE_STATE)change);
		}
	}
}

/* @socom-skeleton stub DecrementTeamValves__8CMissionFP7CEntity */
void CMission::DecrementTeamValves(CEntity *entity)
{
	/* 0x1fccb0 (a seal's death): the player's death clears player_valve_alive; each of
	 * the entity's team valves drops by one (not below 0); callbacks on each change */
	if (entity == ftsPlayer)
	{
		bool changed = m_player_valve->m_value != 0;
		m_player_valve->m_value = 0;

		if (changed)
			m_player_valve->MakeCallbacks((VALVE_STATE)2);
	}

	for (s32 bit = 0; bit < 32; bit++)
	{
		if (!((1 << bit) & entity->m_team))
			continue;

		CValve* valve = m_teamValve[bit];
		u32 old = valve->m_value;
		u32 count = old != 0 ? old - 1 : old;
		u32 change = old != count ? (count != 0 ? 1 : 2) : 0;
		valve->m_value = count;

		if (change)
			valve->MakeCallbacks((VALVE_STATE)change);
	}
}

/* @socom-skeleton stub RecycleEntity__8CMissionFP7CEntity */
void CMission::RecycleEntity(CEntity *entity)
{
	/* 0x1fcc60 (CSealCtrlAi::PostMortemPreTick): while recycle entries wait, a dead AI's
	 * slot is recycled (CEntity::RecycleEntity) and one more spawn is due, 2 s from now */
	if (spawners.m_spawn.empty())
		return;

	spawners.m_timer = 2.0f;
	spawners.m_pending++;
	CEntity::RecycleEntity(entity);
#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("SPAWN: %s recycled (%d due, %u waiting)", entity->m_node != NULL ? entity->m_node->m_name : "-",
		spawners.m_pending, (u32)spawners.m_spawn.size());
#endif
}

/* @socom-skeleton stub Tick__9CSpawnersFf */
void CSpawners::Tick(float dT)
{
	/* 0x1fcb40 (CMission::Tick): for each recycled entity, 2 s later the first waiting
	 * recycle entry is made (in its own m_list slot: OpenRecycler / RecycleEntity), joins its
	 * unit and starts its mission; then it leaves the list. ELF quirk kept: the timer keeps
	 * counting down only while a spawn is due, and an empty list still uses up the spawn. */
	if (m_pending <= 0)
		return;

	m_timer -= dT;

	if (!(m_timer <= 0.0f))
		return;

	if (!m_spawn.empty())
	{
		spawn_map& spawn = m_spawn.front();
		CEntity::OpenRecycler(spawn.m_index);
		CZSealBody* body = theMission.LoadVehicle(spawn.m_entry, false);

		if (body != NULL)
		{
			CEntity::RecycleEntity(spawn.m_index, body, true);
			CSealUnit::InitalizeSealUnit(body->m_type == CEntity::ENT_TYPE_SEAL ? body : NULL);
			body->OnMissionStart();
#ifdef SOCOM_PORT
			SOCOM_PORT_TRACE("SPAWN: %s in slot %u", body->m_node != NULL ? body->m_node->m_name : "-", spawn.m_index);
#endif
		}

		m_spawn.erase(m_spawn.begin());
		m_timer = 2.0f;
		CEntity::CloseRecycler();
	}

	m_pending--;
}

/* @socom-skeleton stub Clear__9CSpawnersFv */
void CSpawners::Clear()
{
	/* 0x1fcb00 (CMission::Close, ReOpen_Unload1): erases the whole spawn_map list (+0xc) */
	m_spawn.clear();
}
